/* BWS website service worker (generated by tools/generate_site.py: edit tools/sw_template.js).
   Keeps a copy of pages and files on the visitor's device so the site still opens on a slow or
   dropped connection. Forms, the BWS Portal and other sites always go straight to the network,
   and nothing personal is stored. */
"use strict";
const VERSION = "1176648f";
const CORE = "bws-core-" + VERSION;   // stylesheet, script, fonts, logo, offline page
const PAGES = "bws-pages";             // pages the visitor has opened
const MEDIA = "bws-media";             // photos, drawings, PDF
const MEDIA_LIMIT = 80;
const PAGE_TIMEOUT = 4000;             // after this, show the saved copy (if any) while the network finishes
const PRECACHE = ["/offline.html", "/assets/css/styles.css?v=1176648f", "/assets/js/main.js?v=1176648f", "/assets/fonts/ibm-plex-serif-700-latin.woff2", "/assets/fonts/ibm-plex-sans-400-latin.woff2", "/assets/fonts/ibm-plex-sans-600-latin.woff2", "/assets/fonts/ibm-plex-sans-700-latin.woff2", "/assets/fonts/noto-naskh-arabic-500-jawi.woff2", "/assets/logo/logo.svg", "/assets/logo/logo-white.svg", "/assets/logo/favicon.svg"];

self.addEventListener("install", (event) => {
  event.waitUntil(caches.open(CORE).then((c) => c.addAll(PRECACHE)).then(() => self.skipWaiting()));
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith("bws-core-") && k !== CORE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

const trim = async (name, limit) => {
  const cache = await caches.open(name);
  const keys = await cache.keys();
  for (let i = 0; i < keys.length - limit; i++) await cache.delete(keys[i]);
};

// Pages: network first. Fall back to the saved copy only when the network is slow or fails.
const page = (request) => new Promise((resolve) => {
  let settled = false;
  const done = (r) => { if (!settled && r) { settled = true; resolve(r); } };
  const cached = () => caches.match(request, { ignoreSearch: true });
  const network = fetch(request).then((response) => {
    if (response.ok) { const copy = response.clone(); caches.open(PAGES).then((c) => c.put(request, copy)); }
    done(response);
    return response;
  }).catch(async () => { done(await cached() || await caches.match("/offline.html")); });
  setTimeout(async () => { const r = await cached(); if (r) done(r); }, PAGE_TIMEOUT);
  return network;
});

// Versioned files: from the device first.
const cacheFirst = async (request, name) => {
  const hit = await caches.match(request);
  if (hit) return hit;
  const response = await fetch(request);
  if (response.ok) (await caches.open(name)).put(request, response.clone());
  return response;
};

// Photos and documents: show the saved copy straight away, refresh it in the background.
const staleWhileRevalidate = async (request) => {
  const cache = await caches.open(MEDIA);
  const hit = await cache.match(request);
  const refresh = fetch(request).then((response) => {
    if (response.ok) cache.put(request, response.clone()).then(() => trim(MEDIA, MEDIA_LIMIT));
    return response;
  }).catch(() => hit);
  return hit || refresh;
};

self.addEventListener("fetch", (event) => {
  const request = event.request;
  if (request.method !== "GET") return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;
  if (request.mode === "navigate") { event.respondWith(page(request)); return; }
  if (/^\/assets\/(css|js|fonts|logo)\//.test(url.pathname)) { event.respondWith(cacheFirst(request, CORE)); return; }
  if (/^\/assets\/(img|illustrations|docs)\//.test(url.pathname)) { event.respondWith(staleWhileRevalidate(request)); return; }
});
